# API එකක් හදලා SMS යැවීම - Class එකක් හැටියට

ඔබට SMS API එකක් integrate කරන්න Class එකක් හදාගන්නේ මෙහෙමයි. පොදුවේ Twilio, Dialog, Text.lk වගේ services වලට මේ pattern එක වැඩ කරයි.

## 1. Basic Structure (PHP උදාහරණයක්)

```php
<?php

class SmsService {
    private $apiUrl;
    private $apiKey;
    private $senderId;

    public function __construct($apiUrl, $apiKey, $senderId) {
        $this->apiUrl = $apiUrl;
        $this->apiKey = $apiKey;
        $this->senderId = $senderId;
    }

    public function sendSms($phoneNumber, $message) {
        // Phone number format කරගන්න
        $phoneNumber = $this->formatNumber($phoneNumber);

        $data = [
            'to' => $phoneNumber,
            'from' => $this->senderId,
            'message' => $message,
        ];

        $ch = curl_init($this->apiUrl);
        curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
        curl_setopt($ch, CURLOPT_POST, true);
        curl_setopt($ch, CURLOPT_POSTFIELDS, json_encode($data));
        curl_setopt($ch, CURLOPT_HTTPHEADER, [
            'Content-Type: application/json',
            'Authorization: Bearer ' . $this->apiKey,
        ]);

        $response = curl_exec($ch);
        $error = curl_error($ch);
        curl_close($ch);

        if ($error) {
            return ['success' => false, 'message' => $error];
        }

        return json_decode($response, true);
    }

    private function formatNumber($number) {
        // 0771234567 -> 94771234567
        if (substr($number, 0, 1) === '0') {
            $number = '94' . substr($number, 1);
        }
        return $number;
    }
}

// Usage
$sms = new SmsService('https://api.example.com/send', 'YOUR_API_KEY', 'MyApp');
$result = $sms->sendSms('0771234567', 'Hello from my app!');
print_r($result);
```

## 2. Node.js Class Version

```javascript
const axios = require('axios');

class SmsService {
    constructor(apiUrl, apiKey, senderId) {
        this.apiUrl = apiUrl;
        this.apiKey = apiKey;
        this.senderId = senderId;
    }

    formatNumber(number) {
        if (number.startsWith('0')) {
            return '94' + number.substring(1);
        }
        return number;
    }

    async sendSms(phoneNumber, message) {
        try {
            const response = await axios.post(this.apiUrl, {
                to: this.formatNumber(phoneNumber),
                from: this.senderId,
                message: message
            }, {
                headers: {
                    'Authorization': `Bearer ${this.apiKey}`,
                    'Content-Type': 'application/json'
                }
            });
            return response.data;
        } catch (error) {
            return { success: false, message: error.message };
        }
    }
}

// Usage
const sms = new SmsService('https://api.example.com/send', 'YOUR_API_KEY', 'MyApp');
sms.sendSms('0771234567', 'Hello!').then(res => console.log(res));
```

## 3. Python Class Version

```python
import requests

class SmsService:
    def __init__(self, api_url, api_key, sender_id):
        self.api_url = api_url
        self.api_key = api_key
        self.sender_id = sender_id

    def format_number(self, number):
        if number.startswith('0'):
            return '94' + number[1:]
        return number

    def send_sms(self, phone_number, message):
        data = {
            'to': self.format_number(phone_number),
            'from': self.sender_id,
            'message': message
        }
        headers = {
            'Authorization': f'Bearer {self.api_key}',
            'Content-Type': 'application/json'
        }
        response = requests.post(self.api_url, json=data, headers=headers)
        return response.json()

# Usage
sms = SmsService('https://api.example.com/send', 'YOUR_API_KEY', 'MyApp')
result = sms.send_sms('0771234567', 'Hello!')
print(result)
```

